  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pirfenidone, a close structural analogue sharing the N-phenyl methylated azacyclic ketone core, is rapidly absorbed and displays high oral bioavailability in humans and nonclinical species, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Urapidil has an absolute oral bioavailability of 78% in healthy volunteers after an oral solution, directly demonstrating high oral bioavailability in a high-transfer analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alogliptin has approximately 100% absolute oral bioavailability in healthy volunteers, providing strong evidence that this structural class achieves high oral exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ondansetron, another high-transfer heteroaromatic drug, has an absolute oral bioavailability of 62 ± 15% in humans, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "DPP-4 inhibitors containing the same N-aryl pyrazolone scaffold are well absorbed after oral administration in humans, with oral bioavailability of 75–87%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability well above 20%, many with absolute measurements of 60–100%. The closest structural analogue, pirfenidone, is reported to have high oral bioavailability. Therefore the query is predicted to have high absolute oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself is present in the supplied evidence.",
    "Most records do not explicitly address the fasted-state condition, though the high bioavailability values are generally not food-dependent for these analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

